const C=window.CLOUDBLITZ_CONTENT;
const root=document.getElementById('app');
const state={view:'dashboard',day:null,sheet:null,search:'',trainer:false,topicIndex:0,asset:null};
const completed=JSON.parse(localStorage.getItem('cloudblitz-cdec-completed')||'{}');
const dayMap=Object.fromEntries(C.days.map(d=>[d.day,d]));
const sheetMap=Object.fromEntries(C.sheets.map(s=>[s.name,s]));
const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));
const assetPath=src=>src?.startsWith('/assets/')?`./dist${src}`:src?.startsWith('./')?src:`./${src}`;
function allTopicIds(){return C.sheets.flatMap(s=>s.rows.map((_,i)=>`${s.name}::${i}`));}
function render(){root.innerHTML=`<div class="app"><header class="topbar"><div class="brand"><button class="icon-btn mobile-menu" onclick="toggleNav()">☰</button><div class="brandmark">CB</div><div><h1>CloudBlitz GenAI Placement Training</h1><small>Digital Placement Training Classroom · 2026</small></div></div><div class="top-actions"><button class="pill-btn" onclick="openSearch()">⌕ Search</button><button class="pill-btn primary" onclick="startTrainer()">Trainer Mode</button></div></header><div class="shell"><aside class="sidebar" id="sidebar">${nav()}</aside><main class="content">${main()}</main></div>${state.asset?assetModal():''}${state.trainer?trainer():''}</div>`;}
function nav(){return `<div class="nav-label">Classroom</div><button class="nav-btn ${state.view==='dashboard'?'active':''}" onclick="go('dashboard')">▦ Dashboard</button><button class="nav-btn ${state.view==='days'?'active':''}" onclick="go('days')">◷ Day-wise Training</button><button class="nav-btn ${state.view==='roadmap'?'active':''}" onclick="go('roadmap')">◆ 12-Day Roadmap</button><div class="nav-label">Resources</div><button class="nav-btn ${state.view==='resumes'?'active':''}" onclick="go('resumes')">▤ Resume Library</button><button class="nav-btn ${state.view==='screenshots'?'active':''}" onclick="go('screenshots')">▣ Screenshot Library</button><button class="nav-btn ${state.view==='documents'?'active':''}" onclick="go('documents')">▧ Documents & SOPs</button><button class="nav-btn ${state.view==='workbook'?'active':''}" onclick="go('workbook')">☷ Workbook Explorer</button><div class="nav-label">Tools</div><button class="nav-btn" onclick="openSearch()">⌕ Global Search</button><button class="nav-btn" onclick="resetProgress()">↺ Reset Progress</button>`}
function main(){if(state.view==='dashboard')return dashboard();if(state.view==='days')return days();if(state.view==='roadmap')return roadmap();if(state.view==='resumes')return resumes();if(state.view==='screenshots')return screenshots();if(state.view==='documents')return documents();if(state.view==='workbook')return workbook();if(state.view==='sheet')return sheetView();return dashboard();}
function dashboard(){const total=C.days.reduce((n,d)=>n+d.topics.length,0);const done=Object.keys(completed).length;return `<section class="hero"><div class="eyebrow">CloudBlitz · GenAI Placement & Training Program</div><h2>Digital Placement Training Classroom</h2><p>Trainer-ready classroom application built directly from the GenAI workbook. Navigate the 12-day program, open source SOPs, resumes and actual screenshots, and conduct sessions without returning to Excel.</p><div class="hero-actions"><button class="btn orange" onclick="go('days')">Start Day-wise Training</button><button class="btn ghost" onclick="startTrainer()">Enter Trainer Mode</button></div></section><div class="stats"><div class="stat"><b>12</b><span>Training Days</span></div><div class="stat"><b>${C.sheets.length}</b><span>Source Worksheets</span></div><div class="stat"><b>${C.assets.length}</b><span>Actual Screenshots / Images</span></div><div class="stat"><b>${done}/${total}</b><span>Topics Completed</span></div></div><div class="section-title"><h3>Training Phases</h3><span class="muted">Source: GenAI 12-Day Roadmap</span></div><div class="grid"><div class="card"><div class="eyebrow">Phase 1</div><h4>Placement & Career Readiness</h4><p class="muted">Day 1–5</p></div><div class="card"><div class="eyebrow">Phase 2</div><h4>Technical & Project Training</h4><p class="muted">Day 6–10</p></div><div class="card"><div class="eyebrow">Phase 3</div><h4>Professional Communication</h4><p class="muted">Day 11–12</p></div></div><div class="section-title"><h3>Continue Training</h3><span class="muted">Your progress is saved locally</span></div><div class="grid">${C.days.slice(0,6).map(dayCard).join('')}</div><div class="footer">CloudBlitz · GenAI · Confidential — Internal Use Only</div>`}
function dayCard(d){const done=d.topics.filter((_,i)=>completed[`${d.day}::${i}`]).length;return `<article class="card click day-card" onclick="openDay('${esc(d.day)}')"><div class="day-num">${d.day.replace('Day ','D')}</div><h4>${esc(d.module)}</h4><p>${d.topics.map(esc).join(' · ')}</p><div class="tag-row"><span class="tag">${d.topics.length} source topics</span><span class="tag">${done}/${d.topics.length} complete</span></div></article>`}
function days(){return `<div class="section-title"><div><h3>12-Day GenAI Training</h3><span class="muted">Use each day as the trainer's classroom sequence.</span></div></div><div class="grid">${C.days.map(dayCard).join('')}</div>`}
function roadmap(){return `<div class="section-title"><div><h3>GenAI 12-Day Roadmap</h3><span class="muted">Exact phase structure from the workbook.</span></div></div><div class="grid">${C.roadmap.rows.slice(2).map(r=>`<div class="card"><div class="eyebrow">${esc(r[0])}</div><h4>${esc(r[1])}</h4><p class="muted">${esc(r[2])}</p></div>`).join('')}</div><div class="section-title"><h3>Day-wise source syllabus</h3></div><div class="resource-list">${C.days.map(d=>`<div class="resource"><div><strong>${esc(d.day)} — ${esc(d.module)}</strong><small>${d.topics.map(esc).join(' · ')}</small></div><button class="pill-btn primary" onclick="openDay('${esc(d.day)}')">Open Day</button></div>`).join('')}</div>`}
function openDay(day){state.day=day;state.view='sheet';state.topicIndex=0;render()}
function sheetView(){const d=dayMap[state.day];const names=C.mapping[state.day.replace('Day ','')];const sheets=names.map(n=>sheetMap[n]).filter(Boolean);return `<div class="section-title"><div><h3>${esc(d.day)} — ${esc(d.module)}</h3><span class="muted">Source material mapped to this training day.</span></div><button class="pill-btn primary" onclick="startTrainer()">Trainer Mode</button></div><div class="notice">Trainer workflow: explain the source topic → open supporting screenshot/resume/document → demonstrate → mark topic complete → move next.</div><div class="section-title"><h3>Topics</h3></div><div class="resource-list">${d.topics.map((t,i)=>`<div class="resource"><div><strong>${esc(t)}</strong><small>${completed[`${d.day}::${i}`]?'Completed':'Not completed'}</small></div><button class="pill-btn ${completed[`${d.day}::${i}`]?'':'primary'}" onclick="startTrainer(${i})">${completed[`${d.day}::${i}`]?'Review':'Teach Topic'}</button></div>`).join('')}</div><div class="section-title"><h3>Mapped source worksheets</h3></div><div class="resource-list">${sheets.map(s=>`<div class="resource"><div><strong>${esc(s.name)}</strong><small>${s.rows.length} source rows · ${s.assets.length} embedded asset(s)</small></div><button class="pill-btn" onclick="openSheet('${esc(s.name)}')">Open Source</button></div>`).join('')}</div>`}
function openSheet(n){state.sheet=n;state.view='workbook';render()}
function workbook(){return `<div class="section-title"><div><h3>Workbook Explorer</h3><span class="muted">All 17 worksheets are preserved as source reference.</span></div></div><div class="searchbar"><input id="sheetSearch" placeholder="Search worksheets..." oninput="filterSheets(this.value)"/><select class="filter" onchange="filterSheets(this.value)"><option value="">All worksheets</option>${C.sheets.map(s=>`<option>${esc(s.name)}</option>`).join('')}</select></div><div class="resource-list" id="sheetList">${C.sheets.map(s=>`<div class="resource"><div><strong>${esc(s.name)}</strong><small>${s.rows.length} rows${s.assets.length?` · ${s.assets.length} embedded image(s)`:''}</small></div><button class="pill-btn" onclick="openSheet('${esc(s.name)}')">Open</button></div>`).join('')}</div>${state.sheet?renderSheetTable(sheetMap[state.sheet]):''}`}
function renderSheetTable(s){if(!s)return '';return `<div class="section-title"><h3>${esc(s.name)}</h3></div><div class="table-wrap"><table class="sheet-table">${s.rows.map(r=>`<tr>${r.map(c=>`<td>${esc(c)}</td>`).join('')}</tr>`).join('')}</table></div>${s.assets.length?`<div class="section-title"><h3>Embedded source assets</h3></div><div class="asset-grid">${s.assets.map(a=>`<div class="asset-card" onclick="openAsset('${esc(a.src)}','${esc(a.label)}')"><img src="${assetPath(esc(a.src))}" alt="${esc(a.label)}"/><div>${esc(a.label)}</div></div>`).join('')}</div>`:''}`}
function resumes(){const names=['Sample Resume — Fresher','Sample Resume — Experienced'];return `<div class="section-title"><div><h3>Resume Library</h3><span class="muted">Actual resume content extracted from the workbook.</span></div></div><div class="grid">${names.map(n=>`<div class="card click" onclick="openResume('${esc(n)}')"><div class="day-num">CV</div><h4>${esc(n)}</h4><p class="muted">${sheetMap[n].rows.length} source rows · printable viewer</p></div>`).join('')}</div>${state.sheet&&names.includes(state.sheet)?`<div class="section-title"><h3>${esc(state.sheet)}</h3><button class="pill-btn" onclick="window.print()">Print Resume</button></div>${resumeRender(sheetMap[state.sheet])}`:''}`}
function openResume(n){state.sheet=n;state.view='resumes';render()}
function resumeRender(s){const rows=s.rows;return `<div class="resume-view"><div class="resume">${rows.map(r=>{const text=r.filter(Boolean).join('  ');if(!text)return '';let cls='rline';if(/^(PROFESSIONAL SUMMARY|INTERNSHIP EXPERIENCE|WORK EXPERIENCE|TECHNICAL SKILLS|GenAI PROJECTS|CERTIFICATIONS|EDUCATION|LANGUAGES|SAMPLE RESUME)/i.test(text))cls='rhead';else if(/^(Project \d|GenAI Engineer Intern|Senior GenAI Engineer|GenAI Engineer)/i.test(text))cls='rsub';return `<div class="${cls}">${esc(text)}</div>`}).join('')}</div></div>`}
function screenshots(){return `<div class="section-title"><div><h3>Screenshot Library</h3><span class="muted">Actual images embedded in the workbook.</span></div></div><div class="asset-grid">${C.assets.map(a=>`<div class="asset-card" onclick="openAsset('${esc(a.src)}','${esc(a.label)}')"><img src="${assetPath(esc(a.src))}" alt="${esc(a.label)}"/><div>${esc(a.label)}</div></div>`).join('')}</div>`}
function documents(){const names=['Introduction SOP','Resume SOP','Naukri Profile SOP','LinkedIn Profile SOP','Documents','Recruitment Workflow','Communication Training','Quick Reference Card'];return `<div class="section-title"><div><h3>Documents & SOP Library</h3><span class="muted">Source-preserved reference material for trainers.</span></div></div><div class="resource-list">${names.map(n=>{const s=sheetMap[n];return `<div class="resource"><div><strong>${esc(n)}</strong><small>${s.rows.length} source rows</small></div><button class="pill-btn" onclick="openSheet('${esc(n)}')">Open SOP</button></div>`}).join('')}</div>`}
function assetModal(){return `<div class="modal" onclick="closeAsset()"><div class="modal-inner" onclick="event.stopPropagation()"><button class="close" onclick="closeAsset()">Close</button><img src="${assetPath(esc(state.asset.src))}" alt="${esc(state.asset.label)}"/><div style="color:#fff;text-align:center;margin-top:10px;font-size:12px">${esc(state.asset.label)}</div></div></div>`}
function trainer(startIndex=0){const d=dayMap[state.day||'Day 1'];const topics=d.topics;const idx=Math.max(0,Math.min(startIndex ?? state.topicIndex,topics.length-1));state.topicIndex=idx;const topic=topics[idx];const key=`${d.day}::${idx}`;const mapped=C.mapping[d.day.replace('Day ','')]||[];const source=mapped.map(n=>sheetMap[n]).find(s=>s&&s.rows.some(r=>r.join(' ').toLowerCase().includes(topic.toLowerCase().split(' ')[0]))) || mapped.map(n=>sheetMap[n]).find(Boolean);const supporting=source?.assets?.[0];return `<div class="trainer"><div class="trainer-head"><div><strong>CloudBlitz Trainer Mode</strong><div class="key">${esc(d.day)} · ${esc(d.module)}</div></div><button class="pill-btn" onclick="exitTrainer()">Exit · Esc</button></div><div class="trainer-body"><section class="trainer-main"><h2>${esc(d.day)} · Topic ${idx+1} of ${topics.length}</h2><h1>${esc(topic)}</h1><div class="trainer-content">${source?sourcePreview(source,topic):'<p>Use the mapped source worksheets from this day to explain the topic. No invented content is shown.</p>'}</div>${supporting?`<div style="margin-top:25px"><button class="btn orange" onclick="openAsset('${esc(supporting.src)}','${esc(supporting.label)}')">Open Actual Screenshot</button></div>`:''}</section><aside class="trainer-side"><h3>Trainer Checklist</h3><label class="check"><input type="checkbox" ${completed[key]?'checked':''} onchange="toggleComplete('${esc(key)}',this.checked)"/> Mark topic complete</label><div class="section-title" style="margin-top:24px"><h3 style="color:#fff">Classroom Flow</h3></div><p class="key">Explain Topic → Show Actual Asset → Demonstrate → Student Activity → Mark Complete → Next Topic</p><div class="progress" style="margin-top:20px"><i style="width:${((idx+1)/topics.length)*100}%"></i></div><p class="key" style="margin-top:8px">${idx+1}/${topics.length} topic position</p><div class="notice" style="margin-top:20px">Source-first mode: content displayed here comes from the workbook. No fabricated training material is added.</div></aside></div><div class="trainer-foot"><div class="key">← Previous · → Next · Esc Exit</div><div><button class="pill-btn" onclick="trainerPrev()">← Previous</button> <button class="pill-btn primary" onclick="trainerNext()">Next →</button></div></div></div>`}
function sourcePreview(s,topic){const hits=s.rows.filter(r=>r.join(' ').toLowerCase().includes(topic.toLowerCase().split(' ')[0])).slice(0,8);const rows=(hits.length?hits:s.rows.slice(0,6));return `<div class="notice" style="margin-bottom:18px">Source worksheet: <strong>${esc(s.name)}</strong></div><table>${rows.map(r=>`<tr>${r.map(c=>`<td>${esc(c)}</td>`).join('')}</tr>`).join('')}</table>`}
function startTrainer(i=0){if(!state.day)state.day='Day 1';state.topicIndex=i;state.trainer=true;render()}
function exitTrainer(){state.trainer=false;render()}
function trainerNext(){const d=dayMap[state.day];if(state.topicIndex<d.topics.length-1){state.topicIndex++;render()}else{const n=Number(state.day.replace('Day ',''));if(n<12){state.day=`Day ${n+1}`;state.topicIndex=0;render()}else{exitTrainer()}}}
function trainerPrev(){if(state.topicIndex>0){state.topicIndex--;render()}else{const n=Number(state.day.replace('Day ',''));if(n>1){state.day=`Day ${n-1}`;state.topicIndex=dayMap[state.day].topics.length-1;render()}}}
function toggleComplete(k,v){if(v)completed[k]=true;else delete completed[k];localStorage.setItem('cloudblitz-cdec-completed',JSON.stringify(completed));render()}
function resetProgress(){if(confirm('Reset all locally saved GenAI topic progress?')){localStorage.removeItem('cloudblitz-cdec-completed');location.reload()}}
function go(v){state.view=v;state.sheet=null;render()}
function openAsset(src,label){state.asset={src,label};render()}
function closeAsset(){state.asset=null;render()}
function openSearch(){const q=prompt('Search CloudBlitz GenAI content:');if(q!==null){state.search=q;search(q)}}
function search(q){const results=[];for(const s of C.sheets){for(const [i,r] of s.rows.entries()){const text=r.join(' ');if(text.toLowerCase().includes(q.toLowerCase()))results.push({s,i,text})}}state.view='workbook';render();setTimeout(()=>{const el=document.querySelector('.content');if(el){const box=document.createElement('div');box.className='card';box.innerHTML=`<h3>Search results for “${esc(q)}”</h3><p class="muted">${results.length} source row(s) found.</p><div class="resource-list">${results.slice(0,50).map(x=>`<div class="resource"><div><strong>${esc(x.s.name)} · Row ${x.i+1}</strong><small>${esc(x.text)}</small></div><button class="pill-btn" onclick="openSheet('${esc(x.s.name)}')">Open Sheet</button></div>`).join('')||'<div class="empty">No matching source content found.</div>'}</div>`;el.prepend(box)}},0)}
render();
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&state.asset){closeAsset();return}if(e.key==='Escape'&&state.trainer){exitTrainer();return}if(state.trainer&&e.key==='ArrowRight'){trainerNext()}if(state.trainer&&e.key==='ArrowLeft'){trainerPrev()}});